import React, { useState, useEffect, useRef } from 'react';
import { Search, ChevronDown, Check } from 'lucide-react';

const LanguageSelector = ({ languages, selectedLang, onSelectLanguage }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const containerRef = useRef(null);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (containerRef.current && !containerRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const langList = Object.entries(languages || {}).map(([code, meta]) => ({
    code,
    ...meta
  }));

  const filtered = langList.filter(l => 
    l.name.toLowerCase().includes(search.toLowerCase()) ||
    l.native.toLowerCase().includes(search.toLowerCase()) ||
    l.code.toLowerCase().includes(search.toLowerCase())
  );

  const currentMeta = languages[selectedLang] || { name: 'Select Language', flag: '🌐', native: '' };

  return (
    <div ref={containerRef} style={{ position: 'relative', width: '250px', zIndex: 1000 }}>
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="glass-panel"
        type="button"
        style={{
          width: '100%',
          display: 'flex',
          alignItems: 'center',
          justify: 'space-between',
          padding: '8px 14px',
          color: '#fff',
          cursor: 'pointer',
          border: '1px solid rgba(255, 255, 255, 0.15)',
          background: 'rgba(17, 24, 39, 0.85)',
          borderRadius: '12px',
          transition: 'all 0.2s ease'
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <span style={{ fontSize: '20px' }}>{currentMeta.flag}</span>
          <div style={{ textAlign: 'left' }}>
            <div style={{ fontWeight: 600, fontSize: '13px', lineHeight: '1.2' }}>{currentMeta.name}</div>
            <div style={{ fontSize: '11px', color: '#9ca3af' }}>{currentMeta.native}</div>
          </div>
        </div>
        <ChevronDown size={16} color="#9ca3af" style={{ transform: isOpen ? 'rotate(180deg)' : 'rotate(0)', transition: 'transform 0.2s' }} />
      </button>

      {isOpen && (
        <div 
          className="glass-panel"
          style={{
            position: 'absolute',
            top: '52px',
            right: 0,
            width: '280px',
            maxHeight: '340px',
            overflowY: 'auto',
            zIndex: 1000,
            padding: '10px',
            background: 'rgba(15, 23, 42, 0.98)',
            boxShadow: '0 12px 30px rgba(0, 0, 0, 0.6)',
            border: '1px solid rgba(255, 255, 255, 0.2)'
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', padding: '8px 12px', background: 'rgba(255, 255, 255, 0.08)', borderRadius: '8px', marginBottom: '10px' }}>
            <Search size={14} color="#9ca3af" />
            <input 
              type="text" 
              placeholder="Search 51 languages..." 
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              style={{
                background: 'transparent',
                border: 'none',
                color: '#fff',
                outline: 'none',
                width: '100%',
                fontSize: '13px'
              }}
            />
          </div>

          {filtered.length === 0 ? (
            <div style={{ padding: '12px', fontSize: '12px', color: '#9ca3af', textAlign: 'center' }}>No language found</div>
          ) : (
            filtered.map((l) => {
              const isSelected = selectedLang === l.code;
              return (
                <div 
                  key={l.code}
                  onClick={() => {
                    onSelectLanguage(l.code);
                    setIsOpen(false);
                  }}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    justify: 'space-between',
                    padding: '9px 12px',
                    borderRadius: '8px',
                    cursor: 'pointer',
                    background: isSelected ? 'rgba(139, 92, 246, 0.3)' : 'transparent',
                    marginBottom: '2px',
                    transition: 'background 0.15s ease'
                  }}
                  onMouseEnter={(e) => {
                    if (!isSelected) e.currentTarget.style.background = 'rgba(255, 255, 255, 0.08)';
                  }}
                  onMouseLeave={(e) => {
                    if (!isSelected) e.currentTarget.style.background = 'transparent';
                  }}
                >
                  <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                    <span style={{ fontSize: '18px' }}>{l.flag}</span>
                    <div>
                      <div style={{ fontSize: '13px', fontWeight: isSelected ? 600 : 400, color: '#fff' }}>{l.name}</div>
                      <div style={{ fontSize: '11px', color: '#9ca3af' }}>{l.native}</div>
                    </div>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                    {l.dir === 'rtl' && <span className="badge-tag" style={{ fontSize: '9px', padding: '2px 5px' }}>RTL</span>}
                    {isSelected && <Check size={14} color="#c084fc" />}
                  </div>
                </div>
              );
            })
          )}
        </div>
      )}
    </div>
  );
};

export default LanguageSelector;
